SELECT id, channel, promo_code, ends_on, FIRST_VALUE(channel) IGNORE NULLS OVER (PARTITION BY promo_code ORDER BY discount_pct, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_channel, AVG(discount_pct) OVER (ORDER BY starts_on, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS discount_pct_avg_5, ROUND(discount_pct / SUM(discount_pct) OVER (PARTITION BY channel), 4) AS discount_pct_share FROM promotions;
